inputs.verifier:
import hashlib, json, os, sys, zipfile
from collections import Counter
from pathlib import Path

args = json.load(sys.stdin)
op = args["op"]
src = Path(args["src"])

def sha(b):
    return hashlib.sha256(b).hexdigest()

if op == "hash":
    files = []
    for p in sorted(src.rglob("*")):
        if p.is_file():
            files.append({"rel": p.relative_to(src).as_posix(), "size": p.stat().st_size, "sha256": sha(p.read_bytes())})
    digest = sha(json.dumps(files, sort_keys=True).encode())
    result = {"files": files, "digest": digest, "count": len(files)}
elif op == "verify":
    need = args["files"]
    with zipfile.ZipFile(args["zip"]) as zf:
        names = zf.namelist()
        counts = Counter(names)
        dups = sorted(n for n, c in counts.items() if c > 1)
        dirs = sorted(n for n in names if n.endswith("/"))
        extra = sorted(set(names) - set(need))
        absent = sorted(set(need) - set(names))
        mismatch = []
        verified = 0
        for rel in need:
            if rel not in counts:
                continue
            if zf.read(rel) == (src / rel).read_bytes() and sha(zf.read(rel)) == sha((src / rel).read_bytes()):
                verified += 1
            else:
                mismatch.append(rel)
        bad = zf.testzip()
    ok = not dups and not dirs and not extra and not absent and not mismatch and bad is None and verified == len(need) and len(names) == len(need)
    result = {"ok": ok, "entries": len(names), "names_equal": set(names) == set(need), "duplicates": dups, "dir_entries": dirs, "extra": extra, "absent": absent, "byte_mismatch": mismatch, "crc_bad": bad, "verified_count": verified}
else:
    raise SystemExit("unknown op")

path = Path(os.environ["INDIEBIZ_SCRIPT_RESULT"])
tmp = path.with_suffix(".tmp")
tmp.write_text(json.dumps(result, ensure_ascii=False), encoding="utf-8")
tmp.replace(path)

